--comment: Baseline: view direct.appraisers_new as of 2026-10-19. Edit this file in place for later changes.
CREATE OR REPLACE VIEW direct.appraisers_new ON CLUSTER '{cluster}' (`Appraiser` Nullable(String), `Appraiser_Name_In_QuickBooks` Nullable(String), `Appraiser_Company_Name` Nullable(String), `Appraiser_Name_On_Check` Nullable(String), `Appraiser_Status` Nullable(String), `Appraiser_Type` Nullable(String), `Appraiser_EIN` Nullable(String), `Appraiser_Fax` Nullable(String), `Appraiser_Phone_Number1` Nullable(String), `Appraiser_Phone_Number2` Nullable(String), `Appraiser_Email_Address` Nullable(String), `Accounting_System_ID` Nullable(String), `Active_Order_Count` Int32, `Late_Order_Count` Int32, `On_Hold_Order_Count` Int32, `Completed_Order_Count` Int32, `Declined_Orders_Count` Int32, `Street_Address` Nullable(String), `City` Nullable(String), `State_Code` Nullable(String), `Zip` Nullable(String), `Mailing_Street_Address` Nullable(String), `Mailing_City` Nullable(String), `Mailing_State` Nullable(String), `Mailing_Zip` Nullable(String), `Certification_Type` Nullable(String), `Is_FHA_Certified?` Nullable(Bool), `Is_VA_Certified?` Nullable(Bool), `IS_Residential?` Nullable(Bool), `IS_Green_Certified?` Nullable(Bool), `Is_Commercial_Appraiser?` Nullable(Bool), `IS_NYS_Board_Approved?` Nullable(Bool), `Is_Chase_Approved?` Nullable(Bool), `Is_Wells_Fargo_Approved?` Nullable(Bool), `Is_Flagstar_Approved?` Nullable(Bool), `Is_TALCB_Approved?` Nullable(Bool), `Is_Venta_Approved?` Nullable(Bool), `On_FNM_Exclusionary_List?` Nullable(Bool), `On_FRE_Exclusionary_List?` Nullable(Bool), `Insurance_Beneficiary` Nullable(String), `Insurance_Policy_Number` Nullable(String), `Insurance_Company` Nullable(String), `Insurance_Expiration_Date` Nullable(DateTime64(3)), `Insurance_Coverage_Amount` Nullable(Decimal(18, 2)), `Insurance_Per_Incident_Coverage_Amount` Nullable(Decimal(18, 2)), `Is_Reviewer?` Nullable(Bool), `Auto_Assignment_On_Review_Orders?` Nullable(Bool), `Appraiser_Fee_Percentage` Nullable(Decimal(18, 2)), `Reviewer_Fee_Percentage` Nullable(Decimal(18, 2)), `Residential_Reviewer_Fee_Amount` Nullable(Decimal(18, 2)), `Commercial_Reviewer_Fee_Amount` Nullable(Decimal(18, 2)), `Preferred_Payment_Method` Nullable(String), `Wants_Work?` Nullable(Bool), `Accepts_Broadcast_Orders?` Nullable(Bool), `Rating` Nullable(Int32), `Auto_Accept_Order?` Nullable(Bool), `Is_Problem_Vendor?` Nullable(Bool), `Is_Preferred_Vendor?` Nullable(Bool), `Is_Trial_Vendor?` Nullable(Bool), `Pause_Automated_Alerts?` Nullable(Bool), `Eligible_For_Order_Auto_Assignment?` Nullable(Bool), `Software_Used` Nullable(String), `Appraiser_Added_On` DateTime64(3), `Appraiser_Added_By_User` Nullable(String), `Appraiser_Last_Updated_On` Nullable(DateTime64(3)), `Appraiser_Last_Updated_By_User` Nullable(String), `AppraiserID` Int32, `Vendor_Type_Name` Nullable(String), `Vendor_Type_ID` Nullable(Int32), `Is_ACHWorks_Account_Available` String, `ACHWorks_Cust_Token_ID` Nullable(String), `Approved_By` Nullable(String), `Approved_On` Nullable(DateTime64(3)), `Qualification` Nullable(String), `Appraiser_Cell_Phone_Number` Nullable(String), `Vendor_Score` Nullable(Int32), `tenant` LowCardinality(String)) DEFINER = default SQL SECURITY DEFINER AS WITH orders AS (SELECT _tenant AS tenant, Assigned_To_Appraiser AS vendor_id, countIf(Appraisal_Status_ID NOT IN (6, 7, 8)) AS active_cnt, countIf(Appraisal_Status_ID = 9) AS onhold_cnt, countIf(Appraisal_File_Released_On IS NOT NULL) AS complete_cnt, countIf((Appraisal_File_Released_On IS NOT NULL) AND (toDate(Appraisal_File_Original_Submission_Date) > toDate(Appraiser_Due_Date))) AS late_cnt FROM raw.appraisals FINAL WHERE (__deleted = 'false') AND (Assigned_To_Appraiser IS NOT NULL) GROUP BY _tenant, Assigned_To_Appraiser), declines AS (SELECT tenant, vendor_id, count() AS cnt FROM analytics.vendor_declines FINAL GROUP BY tenant, vendor_id), quals AS (SELECT tenant, vendor_id, arrayStringConcat(arraySort(groupArray(frag)), ', ') AS Qualification FROM (SELECT tenant, vendor_id, group_name, concat(group_name, ' (', arrayStringConcat(arraySort(groupArray(type_name)), ','), ') ') AS frag FROM (SELECT v.tenant AS tenant, v.vendor_id AS vendor_id, qg.name AS group_name, qt.name AS type_name FROM analytics.vendor_qualifications AS q FINAL INNER JOIN analytics.vendors AS v FINAL ON (v.vendor_id = q.vendor_id) AND (v.tenant = q.tenant) INNER JOIN analytics.qualification_types AS qt FINAL ON (qt.qualification_type_id = q.qualification_type_id) AND (qt.tenant = q.tenant) INNER JOIN analytics.qualification_groups AS qg FINAL ON (qg.qualification_group_id = qt.qualification_group_id) AND (qg.tenant = qt.tenant) INNER JOIN analytics.vendor_types AS vt FINAL ON (vt.vendor_type_id = v.vendor_type_id) AND (vt.tenant = v.tenant) LEFT JOIN analytics.vendor_type_qualification_groups AS vtq FINAL ON (vtq.vendor_type_id = vt.vendor_type_id) AND (vtq.qualification_group_id = qg.qualification_group_id) AND (vtq.tenant = vt.tenant) WHERE (vt.only_use_selected_qualification_groups = 0) OR (vtq.vendor_type_id IS NOT NULL)) GROUP BY tenant, vendor_id, group_name) GROUP BY tenant, vendor_id) SELECT v.vendor_name AS Appraiser, v.qb_name AS Appraiser_Name_In_QuickBooks, v.company_name AS Appraiser_Company_Name, v.name_on_check AS Appraiser_Name_On_Check, st.name AS Appraiser_Status, et.name AS Appraiser_Type, v.ein AS Appraiser_EIN, v.fax AS Appraiser_Fax, v.phone1 AS Appraiser_Phone_Number1, v.phone2 AS Appraiser_Phone_Number2, v.email AS Appraiser_Email_Address, if(v.accounting_system_id = '', NULL, v.accounting_system_id) AS Accounting_System_ID, toInt32(ifNull(o.active_cnt, 0)) AS Active_Order_Count, toInt32(ifNull(o.late_cnt, 0)) AS Late_Order_Count, toInt32(ifNull(o.onhold_cnt, 0)) AS On_Hold_Order_Count, toInt32(ifNull(o.complete_cnt, 0)) AS Completed_Order_Count, toInt32(ifNull(d.cnt, 0)) AS Declined_Orders_Count, v.address AS Street_Address, v.city AS City, v.state_code AS State_Code, v.zip AS Zip, v.mailing_address AS Mailing_Street_Address, v.mailing_city AS Mailing_City, v.mailing_state_code AS Mailing_State, v.mailing_zip AS Mailing_Zip, ct.name AS Certification_Type, v.fha_certified AS `Is_FHA_Certified?`, v.va_certified AS `Is_VA_Certified?`, v.residential AS `IS_Residential?`, v.green_certified AS `IS_Green_Certified?`, v.commercial AS `Is_Commercial_Appraiser?`, v.nys_board_approved AS `IS_NYS_Board_Approved?`, v.chase_approved AS `Is_Chase_Approved?`, v.wells_fargo_approved AS `Is_Wells_Fargo_Approved?`, v.flagstar_approved AS `Is_Flagstar_Approved?`, v.talcb_approved AS `Is_TALCB_Approved?`, v.venta_approved AS `Is_Venta_Approved?`, v.on_fannie_mae_dnu_list AS `On_FNM_Exclusionary_List?`, v.on_freddie_mac_dnu_list AS `On_FRE_Exclusionary_List?`, v.insurance_beneficiary_name AS Insurance_Beneficiary, v.insurance_policy_number AS Insurance_Policy_Number, v.insurance_company_name AS Insurance_Company, v.insurance_exp_date AS Insurance_Expiration_Date, v.insurance_coverage_amount AS Insurance_Coverage_Amount, v.insurance_per_incident_coverage_amount AS Insurance_Per_Incident_Coverage_Amount, v.is_reviewer AS `Is_Reviewer?`, v.auto_assign_review_orders AS `Auto_Assignment_On_Review_Orders?`, v.fee_rate AS Appraiser_Fee_Percentage, v.review_fee_rate AS Reviewer_Fee_Percentage, v.default_review_fee AS Residential_Reviewer_Fee_Amount, v.default_commercial_review_fee AS Commercial_Reviewer_Fee_Amount, v.preferred_payment_method AS Preferred_Payment_Method, v.wants_work AS `Wants_Work?`, v.send_broadcast AS `Accepts_Broadcast_Orders?`, v.rating AS Rating, v.auto_accept_orders AS `Auto_Accept_Order?`, v.is_problem_vendor AS `Is_Problem_Vendor?`, v.is_preferred_vendor AS `Is_Preferred_Vendor?`, v.is_trial_vendor AS `Is_Trial_Vendor?`, v.pause_order_related_automated_alerts AS `Pause_Automated_Alerts?`, v.eligible_for_order_auto_assignment AS `Eligible_For_Order_Auto_Assignment?`, sw.name AS Software_Used, v.created_on AS Appraiser_Added_On, v.created_by AS Appraiser_Added_By_User, v.last_modified_on AS Appraiser_Last_Updated_On, v.last_modified_by AS Appraiser_Last_Updated_By_User, v.vendor_id AS AppraiserID, vt.name AS Vendor_Type_Name, v.vendor_type_id AS Vendor_Type_ID, if(v.ach_works_cust_token_id IS NOT NULL, 'True', 'False') AS Is_ACHWorks_Account_Available, v.ach_works_cust_token_id AS ACHWorks_Cust_Token_ID, v.approved_by AS Approved_By, v.approved_on AS Approved_On, qz.Qualification AS Qualification, v.cell_phone_number AS Appraiser_Cell_Phone_Number, v.score AS Vendor_Score, v.tenant AS tenant FROM analytics.vendors AS v FINAL LEFT JOIN analytics.vendor_engagement_types AS et FINAL ON (et.engagement_type_id = v.engagement_type_id) AND (et.tenant = v.tenant) LEFT JOIN analytics.vendor_statuses AS st FINAL ON (st.status_id = v.status_id) AND (st.tenant = v.tenant) LEFT JOIN analytics.vendor_cert_types AS ct FINAL ON (ct.cert_type_id = v.cert_type_id) AND (ct.tenant = v.tenant) LEFT JOIN analytics.vendor_software AS sw FINAL ON (sw.software_type_id = v.software_type_id) AND (sw.tenant = v.tenant) LEFT JOIN analytics.vendor_types AS vt FINAL ON (vt.vendor_type_id = v.vendor_type_id) AND (vt.tenant = v.tenant) LEFT JOIN declines AS d ON (d.vendor_id = v.vendor_id) AND (d.tenant = v.tenant) LEFT JOIN quals AS qz ON (qz.vendor_id = v.vendor_id) AND (qz.tenant = v.tenant) LEFT JOIN orders AS o ON (o.vendor_id = v.vendor_id) AND (o.tenant = v.tenant) WHERE (v.is_deactivated = 0) AND (vt.is_active = 1) SETTINGS join_use_nulls = 1;
--rollback DROP VIEW IF EXISTS direct.appraisers_new ON CLUSTER '{cluster}' SYNC;